#include <stdlib.h>

#include <fstream>
#include <map>
#include <sstream>
#include <string>
#include <vector>

#include "check.h"
#include "rules/weapons.h"

// data/rows/feat.mastery.txt and its strings are generated by
// tools/data/mastery_feats.py from its own copy of the weapon table; this
// checks them against the C++ one (rules/weapons.cpp). Breaks caught: a row
// for the wrong weapon (an id saved in characters pointing elsewhere), a
// weapon missing a row, a proficiency prerequisite drifting from the
// weapon's proficiency feats, a name string with the wrong mastery property.
namespace {

std::string Upper(std::string text) {
  for (char& c : text) c = (c == ' ' || c == '-') ? '_' : static_cast<char>(toupper(static_cast<unsigned char>(c)));
  return text;
}

std::map<unsigned long, std::string> ReadStrings() {
  std::map<unsigned long, std::string> strings;
  std::ifstream file("data/strings.txt");
  std::string line;
  while (std::getline(file, line)) {
    if (!line.empty() && line.back() == '\r') line.pop_back();
    if (line.size() < 10 || line[0] == '#') continue;
    strings[strtoul(line.c_str(), nullptr, 10)] = line.substr(9);
  }
  return strings;
}

}  // namespace

TEST(MasteryFeatRowsMatchTheWeaponTable) {
  std::ifstream file("data/rows/feat.mastery.txt");
  CHECK_EQ(file.good(), true);
  const std::map<unsigned long, std::string> strings = ReadStrings();
  std::string line;
  bool header = true;
  int rows = 0, wrong = 0;
  while (std::getline(file, line)) {
    if (!line.empty() && line.back() == '\r') line.pop_back();
    if (line.empty() || line[0] == '#') continue;
    if (header) {  // LABEL FEAT DESCRIPTION ICON ... MASTERFEAT OrReqFeat0..4 ...
      header = false;
      continue;
    }
    std::istringstream in(line);
    std::vector<std::string> cells;
    for (std::string cell; in >> cell;) cells.push_back(cell);
    if (cells.size() < 15) {
      ++wrong;
      continue;
    }
    ++rows;
    const int id = atoi(cells[0].c_str());
    const int kind = rules::WeaponKindOfMasteryFeat(id);
    const char* name = kind >= 0 ? rules::NwnWeaponName(kind) : nullptr;
    if (!name || cells[1] != "NWN5E_WM_" + Upper(name)) {
      ++wrong;
      printf("  feat.mastery.txt row %d: %s is not %s\n", id, cells[1].c_str(), name ? name : "a weapon");
      continue;
    }
    std::vector<int> required;
    for (int i = 10; i < 15; ++i) {
      if (cells[i] != "****") required.push_back(atoi(cells[i].c_str()));
    }
    if (required != rules::ProficiencyFeatsForNwnBaseItem(kind)) {
      ++wrong;
      printf("  feat.mastery.txt row %d: proficiency feats differ from %s's\n", id, name);
    }
    const auto text = strings.find(strtoul(cells[2].c_str(), nullptr, 10));
    const std::string expected =
        std::string("Weapon Mastery: ") + name + " (" + rules::MasteryName(rules::MasteryForNwnBaseItem(kind)) + ")";
    if (text == strings.end() || text->second != expected) {
      ++wrong;
      printf("  feat.mastery.txt row %d: name string is not \"%s\"\n", id, expected.c_str());
    }
  }
  CHECK_EQ(wrong, 0);
  CHECK_EQ(rows, static_cast<int>(rules::NwnMasteryWeapons().size()));
}
